const cfg = {
  toolsUrl: ($env.EXCEL_TOOLS_URL || 'http://excel-tools:8000/api/v1').replace(/\/$/, ''),
  toolsApiKey: $env.EXCEL_TOOLS_API_KEY || '',
  qwenBaseUrl: ($env.QWEN_BASE_URL || '').replace(/\/$/, ''),
  qwenApiKey: $env.QWEN_API_KEY || '',
  qwenModel: $env.QWEN_MODEL || 'qwen3.6-plus',
  maxIterations: 12,
  maxToolCalls: 30,
};
const uploaded = $input.first().json;
const original = $('Excel extraction webhook').first().json;

const parseJsonObject = (value, fallback = {}) => {
  if (value === undefined || value === null || value === '') return fallback;
  if (typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : fallback;
    } catch { return fallback; }
  }
  return fallback;
};
const request = parseJsonObject(original.request ?? original.body?.request ?? original.body, {});
const clarificationResponse = parseJsonObject(original.clarification_response ?? original.body?.clarification_response, null);

const finalError = (message, meta = {}) => [{ json: {
  status: 'error', message, next_action: 'handle_error',
  data: { result_id: null, artifact_ref: null, columns: [], records: [], row_count: 0, returned_count: 0, truncated: false, provenance: [] },
  filters_applied: [], field_mapping: {}, assumptions: [], warnings: [], errors: [{ code: 'AGENT_LOOP_ERROR', message }], clarification: null, meta,
}}];
const requestJson = async (url, options = {}) => {
  const response = await helpers.httpRequest({
    url,
    method: options.method || 'GET',
    headers: options.headers || {},
    body: options.body,
    json: true,
    timeout: 120000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  });
  const statusCode = response.statusCode ?? 200;
  const payload = response.body ?? response;
  if (statusCode < 200 || statusCode >= 300) {
    throw new Error(`HTTP ${statusCode} from ${url}: ${JSON.stringify(payload).slice(0, 2000)}`);
  }
  return payload;
};
const toolsHeaders = { 'X-API-Key': cfg.toolsApiKey };

try {
  const sessionId = uploaded.session_id;
  if (typeof sessionId !== 'string' || !sessionId) return finalError('Excel Tools upload did not return session_id');
  if (!cfg.qwenBaseUrl || !cfg.qwenApiKey) return finalError('Qwen endpoint or API key is not configured', { session_id: sessionId });

  const { tools } = await requestJson(`${cfg.toolsUrl}/tools`, { headers: toolsHeaders });
  let recoveredState = null;
  if (clarificationResponse) {
    const resolvePayload = await requestJson(`${cfg.toolsUrl}/sessions/${encodeURIComponent(sessionId)}/tools/batch`, {
      method: 'POST', headers: { ...toolsHeaders, 'Content-Type': 'application/json' },
      body: { calls: [{ call_id: 'resolve_clarification', name: 'resolve_clarification', args: clarificationResponse }] },
    });
    const resolved = resolvePayload.results?.[0];
    if (!resolved?.ok) return finalError('Could not resolve clarification', { session_id: sessionId, tool_error: resolved?.error });
    recoveredState = await requestJson(`${cfg.toolsUrl}/sessions/${encodeURIComponent(sessionId)}/state`, { headers: toolsHeaders });
  }

  let messages = [
    { role: 'system', content: "Ты — агент извлечения данных из Excel.\n\nУ тебя есть доступ только к инструментам сервиса Excel Tools. Excel-файл никогда не передаётся в LLM.\n\nПорядок работы:\n1. Начни с workbook_introspect.\n2. При необходимости используй sheet_preview, затем detect_tables и describe_table.\n3. Перед фильтрацией проверяй допустимые значения list_column_values.\n4. Извлекай данные query_table, проверяй validate_result и экспортируй большие результаты export_result.\n5. При неоднозначности вызови submit_clarification, затем finalize_extraction со status=clarification_needed.\n6. Всегда заканчивай единственным вызовом finalize_extraction.\n\nПравила: не выдумывай данные; не возвращай большие таблицы текстом; фиксируй допущения; при ошибке завершай finalize_extraction со status=error." },
    { role: 'user', content: JSON.stringify({ session_id: sessionId, request, clarification_response: clarificationResponse, recovered_state: recoveredState }) },
  ];
  let totalToolCalls = 0;
  let askedForFinalization = false;

  for (let iteration = 0; iteration < cfg.maxIterations; iteration++) {
    const qwenPayload = await requestJson(`${cfg.qwenBaseUrl}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${cfg.qwenApiKey}` },
      body: { model: cfg.qwenModel, temperature: 0, messages, tools, tool_choice: 'auto' },
    });
    const assistantMessage = qwenPayload.choices?.[0]?.message;
    if (!assistantMessage) return finalError('Qwen response has no choices[0].message', { session_id: sessionId });
    messages.push(assistantMessage);
    const toolCalls = Array.isArray(assistantMessage.tool_calls) ? assistantMessage.tool_calls : [];

    if (toolCalls.length === 0) {
      if (!askedForFinalization) {
        askedForFinalization = true;
        messages.push({ role: 'user', content: 'You must finish by calling finalize_extraction with valid structured output. Do not reply with plain text.' });
        continue;
      }
      return finalError('Model did not call finalize_extraction', { session_id: sessionId, raw: assistantMessage.content || null });
    }
    totalToolCalls += toolCalls.length;
    if (totalToolCalls > cfg.maxToolCalls) return finalError('Agent exceeded maximum tool calls', { session_id: sessionId, total_tool_calls: totalToolCalls });

    const calls = toolCalls.map((toolCall) => {
      let args = {};
      try { args = JSON.parse(toolCall.function?.arguments || '{}'); }
      catch { args = { _invalid_arguments_json: toolCall.function?.arguments || '' }; }
      return { call_id: toolCall.id, name: toolCall.function?.name || '', args };
    });
    const toolPayload = await requestJson(`${cfg.toolsUrl}/sessions/${encodeURIComponent(sessionId)}/tools/batch`, {
      method: 'POST', headers: { ...toolsHeaders, 'Content-Type': 'application/json' }, body: { calls },
    });
    for (const result of toolPayload.results || []) {
      messages.push({ role: 'tool', tool_call_id: result.call_id, content: JSON.stringify(result) });
      if (result.name === 'finalize_extraction' && result.ok) return [{ json: result.result.output }];
    }
  }
  return finalError('Agent exceeded maximum iterations', { session_id: sessionId, max_iterations: cfg.maxIterations });
} catch (error) {
  return finalError(error instanceof Error ? error.message : String(error));
}
